package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class MemoryGraphContextVisibilityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI GRAPH = VF.createIRI("urn:g");

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void clearingExplicitGraphIsVisibleBeforeCommit(boolean includeInferred) {
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));
			connection.add(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"), GRAPH);
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT ?g WHERE { GRAPH ?g {} }", null);
			query.setIncludeInferred(includeInferred);
			assertEquals(GraphAlgebraMode.GRAPH, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var result = query.evaluate()) {
				assertTrue(result.hasNext());
				assertEquals(GRAPH, result.next().getValue("g"));
				assertFalse(result.hasNext());
			}

			connection.begin(IsolationLevels.SNAPSHOT);
			connection.clear(GRAPH);
			assertFalse(connection.hasStatement(null, null, null, includeInferred, GRAPH));
			try (var contexts = connection.getContextIDs()) {
				assertFalse(contexts.hasNext(), "the explicit context view already reflects the clear");
			}
			try (var result = query.evaluate()) {
				assertFalse(result.hasNext(), "an inferred branch must not resurrect the cleared explicit graph");
			}
			connection.rollback();
			try (var result = query.evaluate()) {
				assertTrue(result.hasNext());
				assertEquals(GRAPH, result.next().getValue("g"));
				assertFalse(result.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}
}
